def compute(vars):
    shares_repurchased = vars["v1"]
    authorized_amount = vars["v2"]

    if authorized_amount == 0:
        value = None
    else:
        value = (shares_repurchased / authorized_amount) * 100

    return {
        "value": value,
        "trace": {
            "shares_repurchased": shares_repurchased,
            "authorized_amount": authorized_amount,
            "ratio": None if authorized_amount == 0 else shares_repurchased / authorized_amount,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
